  [20111] = { "両手近接武器で与えるダメージを$N1%上げます。", nil, 0xd2cc2ad8, nil, "um" },
  [20116] = { "パラディンの足元の地面を清め、範囲に入った敵に$D1かけて$N1のHolyダメージを与えます。範囲に入った最初の$N3体の敵は、$D2かけて追加で$N4のダメージを受けます。", nil, 0x7cc61e7f, nil, "um" },
