  [20127] = { "自分へのダメージを与える近接攻撃は、$N1%の確率でブロック率を$N2%上昇させます。効果は$D1、または$N4回のブロックまで持続します。", nil, 0x79f79fde, nil, "um" },
  [20138] = { "Devotion Auraのアーマーボーナスを$N1%増加させ、Auraの効果を受けているパーティメンバーが受けるすべての回復を$N2%増加させます。", nil, 0x09506b57, nil, "um" },
  [20143] = { "アイテムから得るアーマー値を$N1%増加させます。", nil, 0x7e505d7e, nil, "um" },
  [20148] = { "盾が吸収するダメージ量を$N1%増加させます。", nil, 0x34e968db, nil, "um" },
  [20149] = { "盾が吸収するダメージ量を$N1%増加させます。", nil, 0x34e968db, nil, "um" },
  [20150] = { "盾が吸収するダメージ量を$N1%増加させ、ブロック時に$N2%の確率で最大マナの$N3%を回復します。この効果は$N4秒に一度しか発生しません。", nil, 0x0c6407c7, nil, "um" },
  [20154] = { "$D1の間パラディンを聖なる霊で満たし、各近接攻撃に$N2の追加Holyダメージを与える効果を付与します。遅い武器ほど一撃あたりのHolyダメージが大きくなります。パラディンに同時に有効にできるSealは1つだけです。", "近接攻撃が$N1の追加Holyダメージを与えます。", 0xf2abb302, 0xa7417007, "uu" },
  [20162] = { "$D1の間パラディンを十字軍の霊で満たし、近接攻撃力を$N2付与します。さらにパラディンの攻撃速度が$N3%速くなりますが、一撃ごとのダメージは減少します。パラディンに同時に有効にできるSealは1つだけです。\n\nこのSealの力を解き放つと、$D2の間敵を裁き、受けるHolyダメージを最大$N5増加させます。近接攻撃で呪文の効果時間が更新されます。パラディンごとに同時に有効にできるJudgementは1つだけです。", "近接攻撃力が$N1上昇しています。近接攻撃が$N2%速くなりますが、与えるダメージは減少します。", 0x2b89e2f7, 0xf3c132e9, "uu" },
  [20163] = { "$D1の間パラディンを神聖な怒りで満たし、近接攻撃に追加で$N2のHolyダメージを与える効果を付与します。盾を装備している間は、各攻撃で与えたHolyダメージの$N3%に等しい吸収シールドも得ます。パラディンに同時に有効にできるSealは1つだけです。\n\nこのSealの力を解き放つと、敵に$N4のHolyダメージを与え、$D2の間対象を挑発して自分を攻撃させます。", "近接攻撃が$N1の追加Holyダメージを与えます。", 0x820bd33a, 0x02f49abe, "uu" },
  [20164] = { "$D1の間パラディンを正義の霊で満たし、各近接攻撃に一定の確率で$D2の間スタンさせる効果を付与します。パラディンに同時に有効にできるSealは1つだけです。\n\nこのSealの力を解き放つと、$D3の間敵を裁き、逃走できなくします。近接攻撃で呪文の効果時間が更新されます。パラディンごとに同時に有効にできるJudgementは1つだけです。", "近接攻撃に$D1の間スタンさせる可能性があります。", 0x297d1926, 0x0e961291, "uu" },
  [20165] = { "$D1の間パラディンを神聖な光で満たし、各近接攻撃に一定の確率でパラディンを$N2回復する効果を付与します。パラディンに同時に有効にできるSealは1つだけです。\n\nこのSealの力を解き放つと、$D2の間敵を裁き、裁かれた敵に対する近接攻撃に一定の確率で攻撃者を$N4回復する効果を付与します。近接攻撃で呪文の効果時間が更新されます。パラディンごとに同時に有効にできるJudgementは1つだけです。", "近接攻撃に、自身の体力を$N1回復する可能性があります。", 0x4ee2853b, 0x73c9462e, "uu" },
  [20166] = { "$D1の間パラディンを神聖な知恵で満たし、各近接攻撃に一定の確率でパラディンのマナを$N2回復する効果を付与します。パラディンに同時に有効にできるSealは1つだけです。\n\nこのSealの力を解き放つと、$D2の間敵を裁き、裁かれた敵に対する攻撃と呪文に一定の確率で攻撃者のマナを$N4回復する効果を付与します。近接攻撃で呪文の効果時間が更新されます。パラディンごとに同時に有効にできるJudgementは1つだけです。", "近接攻撃に、マナを$N1回復する可能性があります。", 0x0f831d16, 0x6adcff26, "uu" },
  [20174] = { "Blessing of Protectionのクールダウンを$N1分短縮し、Blessing of Freedomの効果時間を$N2秒延長します。", nil, 0x876e8544, nil, "um" },
  [20177] = { "近接攻撃をBlockingした後に$N1%の確率で、周期効果でないクリティカルを受けた後に$N2%の確率で、追加攻撃を得ます。", nil, 0xa14ecc5d, nil, "um" },
