  [20577] = { "使用すると、$D2の間、$N3秒ごとに体力の合計の$N1%とマナの合計の$N2%を回復します。$N5ヤード以内のHumanoidまたはアンデッドの死体にのみ有効です。Cannibalizing中に移動、行動、またはダメージを受けると効果は解除されます。", nil, 0xee269eb1, nil, "um" },
  [20580] = { "発動すると影に紛れ込み、敵に存在を察知される確率を下げます。キャンセルするか移動するまで持続します。戦闘中にこのアビリティを使うと敵に攻撃されにくくなりますが、クールダウンが$N1分に延びます。", "影に溶け込んでいます。", 0x647dd30e, 0x87ac4312, "uu" },
  [20582] = { "回避率が$N1%、移動速度が$N2%増加します。ナイトエルフのローグとドルイドは、Stealth中に$N3レベル高いかのように発見されにくくなります。", nil, 0xbeb476f2, nil, "um" },
