  [20587] = { "$D1の間、スタミナを$N1上昇させ、受ける物理ダメージを$N2軽減します。ただし、筋力と敏捷性が$N4低下し、受ける魔法ダメージが最大$N5増加します。", "強力な酒です。", 0x03beb381, 0x6b5d5caf, "uu" },
  [20589] = { "移動を妨げる効果からただちに逃れ、$D1の間その効果を無効にします。", "移動を妨げる効果が効きません。", 0xb2ba5536, 0xfedffc69, "uu" },
