  [20594] = { "Bleed、Poison、Disease効果をすべて即座に解除して免疫を得るとともに、$D1の間、受けるPhysicalダメージが$N1%減少します。", "Bleed、Poison、Disease効果に対する免疫があります。受けるPhysicalダメージが$N1%減少します。", 0x3ce762ce, 0x9f60da2c, "uu" },
