  [20923] = { "パラディンの足元の地面を清め、範囲に入った敵に$D1かけて$N1のHolyダメージを与えます。範囲に入った最初の$N3体の敵は、$D2かけて追加で$N4のダメージを受けます。", nil, 0x2e289070, nil, "um" },
  [20924] = { "パラディンの足元の地面を清め、範囲に入った敵に$D1かけて$N1のHolyダメージを与えます。範囲に入った最初の$N3体の敵は、$D2かけて追加で$N4のダメージを受けます。", nil, 0x86d9c966, nil, "um" },
  [20925] = { "$D1の間ブロック率を$N1%上昇させ、効果中に攻撃をブロックするたびに$N3のHolyダメージを与えます。Holy Shieldによるダメージは$N4%の追加脅威を発生させます。ブロックするたびにチャージを消費します。チャージ$N5回。", { "ブロック率が$N1%上昇しています。ブロック時、攻撃者に$N2のHolyダメージを与えます。Holy Shieldによるダメージは20%の追加脅威を生みます。残りチャージ$N4回。", "ブロック率が$N1%上昇しています。ブロック時、攻撃者に$N2のHolyダメージを与えます。Holy Shieldによるダメージは20%の追加脅威を生みます。", shape = { "4/0", "3/0" } }, 0x897c3fcd, 0xcc64d1ff, "uu" },
